import { maladumSets } from "../resource/dataSet/setMeta";

// 공포 단계 라벨을 "밴드 번호"로 매핑. 라벨 내부에 어떤 공포명이 포함되는지로 범위를 추정한다.
// Distress < Dismay < Desperation < Doom
const DREAD_ORDER = ["DISQUIET", "DISTRESS", "DISMAY", "DESPERATION", "DISASTER", "DOOM"];

export function allCards() {
    return maladumSets.flatMap(set =>
        set.data.cards.map(card => ({
            ...card,
            setId: set.id,
            setName_ko: set.name_ko,
        }))
    );
}

// 타입 집합 (중복 제거, 정렬)
export function allTypes(cards) {
    const set = new Set();
    for (const c of cards) {
        for (const t of String(c.type || "").split(/[+/,]/)) {
            const trimmed = t.trim();
            if (trimmed) set.add(trimmed);
        }
    }
    return [...set].sort();
}

// 간단 검색: 한글 제목, 영문 제목, 본문
// 검색어가 있으면 세트 필터는 무시하고 전체 세트에서 검색한다
// (영문명은 보통 "어느 세트인지 모를 때" 치는 경우가 많으므로)
export function filterCards(cards, { setId, type, query }) {
    const q = (query || "").trim().toLowerCase();
    const searching = q.length > 0;
    return cards.filter(c => {
        if (!searching && setId && c.setId !== setId) return false;
        if (type) {
            const types = String(c.type || "").split(/[+/,]/).map(t => t.trim());
            if (!types.includes(type)) return false;
        }
        if (searching) {
            const hay = [
                c.card,
                c.card_ko,
                c.type,
                c.type_ko,
                ...(c.sections || []).map(s => s.text_ko || ""),
            ].join(" ").toLowerCase();
            if (!hay.includes(q)) return false;
        }
        return true;
    });
}

// 라벨에 포함된 공포 범위 (시작, 끝 인덱스). 없으면 null.
export function dreadRange(label) {
    const parts = String(label || "").toUpperCase().split("-").map(s => s.trim());
    const indices = parts
        .map(p => DREAD_ORDER.indexOf(p))
        .filter(i => i >= 0);
    if (!indices.length) return null;
    return { start: Math.min(...indices), end: Math.max(...indices) };
}
